BEGIN;
INSERT INTO settings (key, value, updated_at) VALUES ('tagline', '"Handmade natural leather from Iraq."'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('metaTitle', '"أور للجلود | UR Leather — مصنوعات جلدية طبيعية يدوية"'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('metaDescription', '"متجر أور (UR) للمصنوعات الجلدية اليدوية في العراق: محافظ وحقائب وإكسسوارات من جلد طبيعي 100%، ضمان 6 أشهر، وتوصيل لكل المحافظات مع الدفع عند الاستلام."'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('announcement', '"توصيل لكل محافظات العراق · الدفع عند الاستلام · توصيل مجاني للطلبات فوق 150,000 د.ع"'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('supportEmail', '"info@ur-leather.iq"'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('address', '"كركوك - شارع الجمهورية - مجمع ToTU"'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('footerTagline', '"جلد طبيعي.\nصناعة يدوية عراقية."'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('copyrightText', '"أور للجلود — UR Leather"'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('homeHeadline', '"Natural Iraqi leather — Sumerian heritage, made for today."'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('homeHeadlineAr', '"جلد طبيعي عراقي — إرث سومري بروح معاصرة. كل قطعة تُصنع بعناية من جلد طبيعي 100% على أيدي حرفيين عراقيين."'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('homeSubheadline', '"Every piece is cut and stitched by hand."'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('homeSubheadlineAr', '"كل قطعة تُقص وتُخاط باليد."'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('homeValues', '[{"title": "Genuine leather", "titleAr": "جلد طبيعي 100%", "text": "Full-grain leather that ages beautifully.", "textAr": "Full Grain — يكتسب طابعاً أجمل مع الاستخدام."}, {"title": "Handmade", "titleAr": "صناعة يدوية", "text": "By skilled Iraqi craftsmen.", "textAr": "بأيدي حرفيين عراقيين مهرة."}, {"title": "6-month warranty", "titleAr": "ضمان 6 أشهر", "text": "On manufacturing and quality defects.", "textAr": "على عيوب التصنيع والجودة."}, {"title": "Delivery across Iraq", "titleAr": "توصيل لكل العراق", "text": "Pay cash when it arrives.", "textAr": "والدفع عند الاستلام."}]'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
INSERT INTO settings (key, value, updated_at) VALUES ('navigation', '[{"href": "/collection/bestsellers", "name": "Features", "nameAr": "مميزات", "image": "", "caption": "Made to last.", "captionAr": "صُنع ليدوم.", "links": [{"href": "/collection/bestsellers", "label": "Bestsellers", "labelAr": "الأكثر مبيعاً"}, {"href": "/collection/new-releases", "label": "New releases", "labelAr": "وصل حديثاً"}, {"href": "/bundles", "label": "Bundles", "labelAr": "البكجات"}, {"href": "/collection/outlet", "label": "Offers", "labelAr": "العروض والتخفيضات"}]}, {"href": "/products/category/backpacks", "name": "Bags", "nameAr": "حقائب", "image": "", "caption": "Carried with pride.", "captionAr": "جلد يرافقك كل يوم.", "links": [{"href": "/products/category/backpacks", "label": "All bags", "labelAr": "كل الحقائب"}]}, {"href": "/products/category/wallets", "name": "Wallets", "nameAr": "محافظ", "image": "", "caption": "Less bulk. More possibility.", "captionAr": "حجم أقل. مساحة أكبر ليومك.", "links": [{"href": "/products/category/wallets", "label": "All wallets", "labelAr": "كل المحافظ"}]}, {"href": "/products/category/phone-cases", "name": "Phone cases", "nameAr": "كفرات موبايل", "image": "", "caption": "Leather that protects.", "captionAr": "جلد يحمي موبايلك.", "links": [{"href": "/products/category/phone-cases", "label": "iPhone 18 Pro Max", "labelAr": "ايفون 18 PRO MAX"}, {"href": "/products/category/phone-cases", "label": "iPhone 17 Pro Max", "labelAr": "ايفون 17 PRO MAX"}]}, {"href": "/products/category/accessories", "name": "Accessories", "nameAr": "أكسسوارات", "image": "", "caption": "Little things. Big difference.", "captionAr": "تفاصيل صغيرة. فرق كبير.", "links": [{"href": "/products/category/accessories", "label": "All accessories", "labelAr": "كل الاكسسوارات"}]}, {"href": "/info/our-story", "name": "About us", "nameAr": "حولنا", "image": "", "caption": "The story of UR.", "captionAr": "قصة أور.", "links": [{"href": "/info/our-story", "label": "Our story", "labelAr": "قصتنا"}, {"href": "/info/our-materials", "label": "Our leather", "labelAr": "جلودنا"}, {"href": "/info/warranty", "label": "Warranty", "labelAr": "الضمان"}, {"href": "/info/shipping", "label": "Shipping & delivery", "labelAr": "الشحن والتوصيل"}]}]'::jsonb, now()) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = now();
UPDATE settings SET value = jsonb_set(jsonb_set(value, '{groups}', '[{"title": "Help", "titleAr": "مساعدة", "links": [{"label": "Shipping & delivery", "labelAr": "الشحن والتوصيل", "href": "/info/shipping"}, {"label": "Warranty", "labelAr": "الضمان", "href": "/info/warranty"}, {"label": "Leather care", "labelAr": "العناية بالجلد", "href": "/info/care"}, {"label": "Contact us", "labelAr": "تواصل معنا", "href": "/info/contact"}]}, {"title": "Shop", "titleAr": "تسوق", "links": [{"label": "Wallets", "labelAr": "محافظ", "href": "/products/category/wallets"}, {"label": "Bags", "labelAr": "حقائب", "href": "/products/category/backpacks"}, {"label": "Phone cases", "labelAr": "كفرات موبايل", "href": "/products/category/phone-cases"}, {"label": "Accessories", "labelAr": "أكسسوارات", "href": "/products/category/accessories"}, {"label": "Bundles", "labelAr": "البكجات", "href": "/bundles"}]}, {"title": "About us", "titleAr": "حولنا", "links": [{"label": "Our story", "labelAr": "قصتنا", "href": "/info/our-story"}, {"label": "Our leather", "labelAr": "جلودنا", "href": "/info/our-materials"}, {"label": "Stores", "labelAr": "نقاط البيع", "href": "/info/stores"}]}]'::jsonb), '{trustItems}', '[{"icon": "pin", "text": "Iraq", "textAr": "العراق", "active": true, "sortOrder": 0}, {"icon": "globe", "text": "Cash on delivery", "textAr": "الدفع عند الاستلام", "active": true, "sortOrder": 1}, {"icon": "star", "text": "6-month warranty", "textAr": "ضمان 6 أشهر", "active": true, "sortOrder": 2}, {"icon": "badge", "text": "Handmade natural leather", "textAr": "جلد طبيعي صناعة يدوية", "active": true, "sortOrder": 3}]'::jsonb) || jsonb_build_object('newsletter', '{"image": "", "title": "New pieces and offers first", "active": true, "eyebrow": "Get in first", "titleAr": "كن أول من يعرف بالقطع الجديدة والعروض", "eyebrowAr": "اشترك", "description": "New releases and subscriber-only offers.", "descriptionAr": "منتجات جديدة وعروض خاصة للمشتركين."}'::jsonb), updated_at = now() WHERE key = 'footer';
UPDATE settings SET value = jsonb_set(value, '{copy}', (value->'copy') || '{"trendingEyebrow": "Loved by our customers.", "collectionsTitle": "Find your piece", "socialTitle": "UR on Instagram", "socialEyebrow": "From our community", "categoryTitle": "Find your everyday leather piece", "categoryDiscoverTitle": "Natural leather.", "categoryDiscoverLine2": "Made by hand.", "categoryDiscoverTitleAr": "جلد طبيعي.", "categoryDiscoverLine2Ar": "صناعة يدوية."}'::jsonb), updated_at = now() WHERE key = 'homepage';
UPDATE settings SET value = jsonb_set(value, '{blocks}', (SELECT jsonb_agg(CASE WHEN b->>'key' = 'responsible' THEN b || '{"label":"Brand story"}'::jsonb ELSE b END) FROM jsonb_array_elements(value->'blocks') b)), updated_at = now() WHERE key = 'homepage';
UPDATE settings SET value = jsonb_set(value, '{blocks}', (value->'blocks') || '[{"key":"bundles","label":"Bundles","enabled":true,"sortOrder":9}]'::jsonb), updated_at = now() WHERE key = 'homepage' AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(value->'blocks') b WHERE b->>'key' = 'bundles');
UPDATE banners SET active = false, updated_at = now() WHERE image LIKE '/images/hero-%' OR image LIKE '/images/highlight-%';
UPDATE banners SET title = 'Made for every day.', href = regexp_replace(href, '^https?://[^/]+', ''), updated_at = now() WHERE title = 'For all the ways you move.';
UPDATE banners SET title = 'Crafted with care.', title_ar = 'صُنع بإتقان', subtitle = 'Handmade leather goods', subtitle_ar = 'مصنوعات جلدية يدوية فاخرة', cta_label = 'Shop now', cta_label_ar = 'تسوق الآن', href = '/products/category/all', updated_at = now() WHERE title = E'Carry smart.\nMove free.\nGo far.';
UPDATE content_pages SET eyebrow = 'Our story', eyebrow_ar = 'قصتنا', title = 'Iraqi leather. Sumerian roots.', title_ar = 'جلد طبيعي عراقي — إرث سومري بروح معاصرة', subtitle = 'Inspired by the ancient city of Ur in southern Iraq, we make handmade leather goods that join Iraqi heritage with modern design.', subtitle_ar = 'أور - مستوحاة من حضارة أور العريقة في جنوب العراق، نؤمن بأن الحرفة الأصيلة لا تموت. نقدم مصنوعات جلدية يدوية فاخرة تجمع بين عراقة التراث العراقي وأناقة التصميم العصري.', sections = '[{"title": "From Ur to your every day", "text": "UR takes its name from the ancient city of Ur in southern Iraq. We believe true craft never dies — so we make leather goods that carry that heritage into modern life."}, {"title": "100% natural leather, made by hand", "text": "Every piece is made with great care from 100% natural leather by skilled Iraqi craftsmen, giving it a unique character and quality that lasts for years."}, {"title": "An authentic Iraqi mark", "text": "From leather bags to wallets and accessories, every product carries an Iraqi signature and tells a story of craft and precision."}]'::jsonb, sections_ar = '[{"title": "من أور إلى يومك", "text": "أور - مستوحاة من حضارة أور العريقة في جنوب العراق، نؤمن بأن الحرفة الأصيلة لا تموت. نقدم مصنوعات جلدية يدوية فاخرة تجمع بين عراقة التراث العراقي وأناقة التصميم العصري."}, {"title": "جلد طبيعي 100%، صناعة يدوية", "text": "كل قطعة من منتجاتنا تُصنع بعناية فائقة من جلد طبيعي 100% على أيدي حرفيين عراقيين مهرة، مما يمنحها طابعاً فريداً وجودة استثنائية تدوم لسنوات طويلة."}, {"title": "بصمة عراقية أصيلة", "text": "نفتخر بتقديم منتجات تحمل بصمة عراقية أصيلة، من الحقائب الجلدية الفاخرة إلى المحافظ والإكسسوارات المميزة، كل منتج يحكي قصة حرفة وإتقان."}]'::jsonb, updated_at = now() WHERE slug = 'our-story';
UPDATE content_pages SET eyebrow = 'Our leather', eyebrow_ar = 'جلودنا', title = 'Natural leather that gets better with time.', title_ar = 'جلد طبيعي يزداد جمالاً مع الوقت', subtitle = 'We use 100% full-grain natural leather.', subtitle_ar = 'نستخدم جلداً طبيعياً 100% (Full Grain Leather).', sections = '[{"title": "Full-grain leather", "text": "The strongest layer of the hide, kept whole. It wears in, not out."}, {"title": "A character of its own", "text": "Natural leather develops a richer colour and patina with use, so no two pieces look the same after a year."}, {"title": "Made to last", "text": "Careful cutting and strong stitching keep the shape for years."}]'::jsonb, sections_ar = '[{"title": "جلد Full Grain", "text": "أقوى طبقة بالجلد ونتركها كاملة، فيتحمل الاستخدام اليومي ويعيش سنين."}, {"title": "طابع خاص لكل قطعة", "text": "بفضل طبيعته الأصيلة، يكتسب الجلد طابعاً مميزاً مع مرور الوقت، فما تتشابه قطعتين بعد سنة استخدام."}, {"title": "صُنع ليدوم", "text": "قص دقيق وخياطة متينة تحافظ على شكل القطعة لسنوات."}]'::jsonb, updated_at = now() WHERE slug = 'our-materials';
UPDATE content_pages SET eyebrow = 'Warranty', eyebrow_ar = 'الضمان', title = 'A 6-month warranty on every piece.', title_ar = 'ضمان 6 أشهر على جميع المنتجات', subtitle = 'We stand behind what we make.', subtitle_ar = 'نقف خلف كل قطعة نصنعها.', faqs = '[{"question": "Is there a warranty?", "answer": "Yes. Every product has a 6-month warranty from the date of purchase. It covers manufacturing and quality defects, not misuse or deliberate damage."}, {"question": "How do I use the warranty?", "answer": "1. Contact us on WhatsApp or by phone.\n2. Send a photo of the product and describe the problem.\n3. We will repair or replace it free of charge."}]'::jsonb, faqs_ar = '[{"question": "هل يوجد ضمان على المنتجات؟", "answer": "نعم! جميع منتجاتنا مشمولة بضمان لمدة 6 أشهر كاملة من تاريخ الشراء.\n\nيغطي الضمان عيوب التصنيع والجودة.\nالضمان لا يشمل سوء الاستخدام أو التلف المتعمد."}, {"question": "كيف أستفيد من الضمان؟", "answer": "إذا واجهت أي مشكلة في الجودة خلال فترة الضمان:\n\n1. تواصل معنا عبر واتساب أو الهاتف\n2. أرسل صورة للمنتج مع شرح المشكلة\n3. سنقوم بإصلاح أو استبدال المنتج مجاناً"}]'::jsonb, updated_at = now() WHERE slug = 'warranty';
UPDATE content_pages SET eyebrow = 'Leather care', eyebrow_ar = 'العناية بالجلد', title = 'A little care goes a long way.', title_ar = 'عناية بسيطة تخلي الجلد يعيش سنين', subtitle = 'Simple habits keep your leather looking its best.', subtitle_ar = 'عادات بسيطة تحافظ على جمال منتجك الجلدي.', faqs = '[{"question": "How do I care for leather?", "answer": "Use a cotton cloth with a little leather cream, keep it away from heavy moisture, water and direct sun. With regular care it lasts for many years."}]'::jsonb, faqs_ar = '[{"question": "كيف أعتني بالمنتجات الجلدية؟", "answer": "للحفاظ على منتجاتك الجلدية لأطول فترة:\n\n• استخدم قطعة قماش قطنية مع كمية قليلة من كريم العناية بالجلد\n• تجنب تعريض المنتجات للرطوبة الشديدة والماء\n• ابتعد عن أشعة الشمس المباشرة\n• مع العناية المنتظمة، يدوم المنتج لسنوات طويلة"}, {"question": "هل منتجاتكم من جلد طبيعي؟", "answer": "نعم، جميع منتجاتنا مصنوعة من جلد طبيعي 100% (Full Grain Leather).\n\nبفضل طبيعته الأصيلة، يكتسب الجلد طابعاً مميزاً مع مرور الوقت ويحافظ على شكله لسنوات."}]'::jsonb, updated_at = now() WHERE slug = 'care';
UPDATE content_pages SET eyebrow = 'Shipping & delivery', eyebrow_ar = 'الشحن والتوصيل', title = 'Delivered to your door, anywhere in Iraq.', title_ar = 'نوصل لباب بيتك بكل العراق', subtitle = 'Cash on delivery to all governorates.', subtitle_ar = 'توصيل لجميع المحافظات مع الدفع عند الاستلام.', faqs = '[{"question": "When will my order ship?", "answer": "Orders ship within 24 hours."}, {"question": "Where do you deliver?", "answer": "To all Iraqi governorates."}, {"question": "How much is delivery?", "answer": "The delivery fee depends on your governorate and is shown at checkout. Orders over 150,000 IQD ship free."}, {"question": "How do I pay?", "answer": "Cash on delivery — you pay when the order arrives."}]'::jsonb, faqs_ar = '[{"question": "متى يتم شحن طلبي؟", "answer": "جميع الطلبات تُشحن خلال 24 ساعة."}, {"question": "ما هي مناطق التوصيل؟", "answer": "نوصل لجميع المحافظات العراقية."}, {"question": "شكد أجور التوصيل؟", "answer": "أجور التوصيل حسب المحافظة وتظهر عند إتمام الطلب. الطلبات فوق 150,000 د.ع توصيلها مجاني."}, {"question": "شلون أدفع؟", "answer": "الدفع نقداً عند الاستلام — تدفع لما يوصلك الطلب."}]'::jsonb, updated_at = now() WHERE slug = 'shipping';
UPDATE content_pages SET eyebrow = 'Contact us', eyebrow_ar = 'تواصل معنا', title = 'We are here to help.', title_ar = 'نحن هنا لمساعدتك', subtitle = 'Questions about a product or your order? Message us on WhatsApp or leave a message below.', subtitle_ar = 'عندك سؤال عن منتج أو طلبك؟ راسلنا على واتساب أو اترك رسالة هنا.', updated_at = now() WHERE slug = 'contact';
UPDATE content_pages SET published = false, updated_at = now() WHERE slug IN ('responsible-business', 'careers', 'journal', 'corporate-gifting');
COMMIT;
